package main

import (
	"fmt"
	"strings"
	"unicode"
)

type Model struct {
	Engine   string
	Enums    []EnumDef
	Entities []Entity
	Queries  []QueryDef
}

type EnumDef struct {
	Name   string
	GoName string
	Vals   []string
}

type Entity struct {
	Table   string
	Schema  string
	Struct  string
	Key     string
	KeyType string
	KeyBase string
	Version string
	Fields  []Field
}

type Field struct {
	Name    string
	GoName  string
	GoType  string
	Table   string
	Embed   string
	NotNull bool
}

type ParamDef struct {
	Number     int32
	Name       string
	ColumnName string
	GoName     string
	GoType     string
	IsSlice    bool
}

type QueryDef struct {
	Name       string
	Cmd        string
	File       string
	Text       string
	InsertInto string
	Fields     []Field
	Params     []ParamDef
	RowGoType  string
	ArgsName   string
	Slices     []SliceDef
	Embeds     []EmbedDef
}

type SliceDef struct {
	Marker string
	GoName string
	Elem   string
	Spread bool
}

type EmbedDef struct {
	Table  string
	Field  string
	Struct string
}

type tableVersion struct {
	name    string
	version string
}

type claimedBy struct {
	what string
	prev string
}

type catalogTable struct {
	schema string
	table  Table
}

type resolver struct {
	engine      string
	opts        *PluginOptions
	model       *Model
	enums       map[string]string
	enumFlat    map[string]string
	keyed       map[string]string
	keyedBase   map[string]string
	refTypes    map[string]string
	claimed     map[string]claimedBy
	byTable     map[string][]*Entity
	versions    map[string]tableVersion
	seenQueries map[string]bool
}

var skippedSchemas = map[string]bool{
	"pg_catalog":          true,
	"information_schema":  true,
	"pg_temp":             true,
	"sys":                 true,
}

func buildModel(req *Request, opts *PluginOptions) (Model, error) {
	engine := strings.ToLower(req.Settings.Engine)
	if !isEngine(engine) {
		return Model{}, fmt.Errorf("sqlc-gen-spira: unknown engine %q", req.Settings.Engine)
	}
	r := &resolver{
		engine:      engine,
		opts:        opts,
		model:       &Model{Engine: engine},
		enums:       map[string]string{},
		enumFlat:    map[string]string{},
		keyed:       map[string]string{},
		keyedBase:   map[string]string{},
		refTypes:    map[string]string{},
		claimed:     map[string]claimedBy{},
		byTable:     map[string][]*Entity{},
		versions:    map[string]tableVersion{},
		seenQueries: map[string]bool{},
	}
	if err := r.loadCatalog(&req.Catalog); err != nil {
		return Model{}, err
	}
	if err := r.loadQueries(req.Queries); err != nil {
		return Model{}, err
	}
	return *r.model, nil
}


func isEngine(engine string) bool {
	switch engine {
	case "sqlite", "postgresql", "mysql", "mssql":
		return true
	}
	return false
}

func sortTablesByName(tables []Table) {
	for i := 1; i < len(tables); i++ {
		for j := i; j > 0 && tables[j].Rel.Name < tables[j-1].Rel.Name; j-- {
			tables[j], tables[j-1] = tables[j-1], tables[j]
		}
	}
}

func sortCatalog(cat *Catalog) {
	for i := range cat.Schemas {
		sortTablesByName(cat.Schemas[i].Tables)
	}
	for i := 1; i < len(cat.Schemas); i++ {
		for j := i; j > 0 && cat.Schemas[j].Name < cat.Schemas[j-1].Name; j-- {
			cat.Schemas[j], cat.Schemas[j-1] = cat.Schemas[j-1], cat.Schemas[j]
		}
	}
}


func (r *resolver) loadCatalog(cat *Catalog) error {
	sortCatalog(cat)
	tables := collectTables(cat)
	if err := r.indexEnums(cat); err != nil {
		return err
	}
	if err := r.buildKeyed(tables); err != nil {
		return err
	}
	if err := r.buildRefs(tables); err != nil {
		return err
	}
	if err := r.buildVersions(tables); err != nil {
		return err
	}
	for _, ct := range tables {
		if err := r.addEntity(ct); err != nil {
			return err
		}
	}
	return nil
}

func collectTables(cat *Catalog) []catalogTable {
	var out []catalogTable
	for _, sc := range cat.Schemas {
		if skippedSchemas[sc.Name] ?? false {
			continue
		}
		for _, t := range sc.Tables {
			out = append(out, catalogTable{schema: sc.Name, table: t})
		}
	}
	return out
}

func (r *resolver) indexEnums(cat *Catalog) error {
	for _, sc := range cat.Schemas {
		if skippedSchemas[sc.Name] ?? false {
			continue
		}
		for _, e := range sc.Enums {
			gname := goName(sc.Name) + goName(e.Name)
			if err := r.claim(gname, "enum "+sc.Name+"."+e.Name, ""); err != nil {
				return err
			}
			r.enums[strings.ToLower(sc.Name)+"."+strings.ToLower(e.Name)] = gname
			flat := strings.ToLower(e.Name)
			if _, dup := r.enumFlat[flat]; !dup {
				r.enumFlat[flat] = gname
			} else if (r.enumFlat[flat] ?? "") != gname {
				r.enumFlat[flat] = ""
			}
			r.model.Enums = append(r.model.Enums, EnumDef{Name: e.Name, GoName: gname, Vals: e.Vals})
		}
	}
	return nil
}

func (r *resolver) claim(name string, what string, prev string) error {
	if old, dup := r.claimed[name]; dup {
		return fmt.Errorf("sqlc-gen-spira: type name %q claimed by both %s and %s", name, old.what, what)
	}
	r.claimed[name] = claimedBy{what: what, prev: prev}
	return nil
}

func (r *resolver) claimTableType(name string, cur string) error {
	if old, dup := r.claimed[name]; dup {
		return fmt.Errorf("sqlc-gen-spira: tables %q and %q both map to type %s", cur, old.prev, name)
	}
	r.claimed[name] = claimedBy{what: "struct for " + cur, prev: cur}
	return nil
}

func (r *resolver) tableOptsFor(tableName string, tables []catalogTable) (TableOpts, catalogTable, error) {
	ct, err := r.findCatalogTable(tableName, tables)
	if err != nil {
		return TableOpts{}, catalogTable{}, fmt.Errorf("sqlc-gen-spira: tables.%s: %w", tableName, err)
	}
	opts, ok := r.optsFor(ct)
	if !ok {
		return TableOpts{}, catalogTable{}, fmt.Errorf("sqlc-gen-spira: tables.%s has no options entry", tableName)
	}
	return opts, ct, nil
}

func (r *resolver) optsFor(ct catalogTable) (TableOpts, bool) {
	qualified := strings.ToLower(ct.schema) + "." + strings.ToLower(ct.table.Rel.Name)
	if opts, ok := r.opts.Tables[qualified]; ok {
		return opts, true
	}
	var unqualified []string
	for key := range r.opts.Tables {
		if !strings.Contains(key, ".") {
			unqualified = append(unqualified, key)
		}
	}
	sortStrings(unqualified)
	for _, key := range unqualified {
		if strings.ToLower(ct.table.Rel.Name) == key {
			if opts, ok := r.opts.Tables[key]; ok {
				return opts, true
			}
		}
	}
	return TableOpts{}, false
}

func (r *resolver) buildKeyed(tables []catalogTable) error {
	keys := make([]string, 0, len(r.opts.Tables))
	for name := range r.opts.Tables {
		keys = append(keys, name)
	}
	sortStrings(keys)
	for _, name := range keys {
		if err := r.buildKeyedOne(name, tables); err != nil {
			return err
		}
	}
	return nil
}

func (r *resolver) buildKeyedOne(name string, tables []catalogTable) error {
	opts, ct, err := r.tableOptsFor(name, tables)
	if err != nil {
		return err
	}
	if opts.Key == "" {
		if opts.KeyType != "" {
			return fmt.Errorf("sqlc-gen-spira: tables.%s.key_type needs tables.%s.key", name, name)
		}
		return nil
	}
	col, ok := findColumn(&ct.table, opts.Key)
	if !ok {
		return fmt.Errorf("sqlc-gen-spira: tables.%s.key %q is not a column of %s.%s", name, opts.Key, ct.schema, ct.table.Rel.Name)
	}
	base, err := r.baseType(ct.schema, &col)
	if err != nil {
		return err
	}
	keyName, err := r.keyTypeName(name, &ct, opts, base)
	if err != nil {
		return err
	}
	colKey := strings.ToLower(ct.schema) + "." + strings.ToLower(ct.table.Rel.Name) + "." + strings.ToLower(col.Name)
	r.keyed[colKey] = keyName
	r.keyedBase[colKey] = base
	return nil
}

func (r *resolver) keyTypeName(name string, ct *catalogTable, opts TableOpts, base string) (string, error) {
	if opts.KeyType == "" {
		return base, nil
	}
	if !isGoIdent(opts.KeyType) {
		return "", fmt.Errorf("sqlc-gen-spira: tables.%s.key_type %q is not a Go identifier", name, opts.KeyType)
	}
	if err := r.claim(opts.KeyType, "key type of "+ct.table.Rel.Name, ""); err != nil {
		return "", err
	}
	return opts.KeyType, nil
}

func findColumn(t *Table, name string) (Column, bool) {
	for _, c := range t.Columns {
		if c.Name == name || strings.EqualFold(c.Name, name) {
			return c, true
		}
	}
	return Column{}, false
}

func (r *resolver) baseType(schema string, col *Column) (string, error) {
	if col.IsArray {
		return "", fmt.Errorf("%s: column %s is an array", r.columnContext(schema, col), col.Name)
	}
	name := strings.ToLower(col.Type.Name)
	name = strings.TrimPrefix(name, "pg_catalog.")
	if typ, ok := r.opts.Overrides[name]; ok {
		return typ, nil
	}
	if col.Unsigned {
		return "", fmt.Errorf("%s: column %s is unsigned; add an overrides entry for %q", r.columnContext(schema, col), col.Name, name)
	}
	if typ, ok := r.enumGoType(schema, name); ok {
		return typ, nil
	}
	if typ, ok := sqlBaseType(r.engine, name, col.Length); ok {
		return typ, nil
	}
	return "", fmt.Errorf("%s: column %s has unmapped type %q", r.columnContext(schema, col), col.Name, name)
}

func (r *resolver) columnContext(schema string, col *Column) string {
	if col.Table.Name != "" {
		return strings.ToLower(schema) + "." + strings.ToLower(col.Table.Name) + "." + strings.ToLower(col.Name)
	}
	return strings.ToLower(schema) + "." + strings.ToLower(col.Name)
}

func (r *resolver) enumGoType(schema string, name string) (string, bool) {
	if typ, ok := r.enums[strings.ToLower(schema)+"."+name]; ok {
		return typ, true
	}
	if typ, ok := r.enumFlat[name]; ok && typ != "" {
		return typ, true
	}
	return "", false
}

func sqlBaseType(engine string, name string, length int32) (string, bool) {
	switch engine {
	case "sqlite":
		return sqliteBaseType(name)
	case "postgresql":
		return postgresBaseType(name)
	case "mysql":
		return mysqlBaseType(name, length)
	case "mssql":
		return mssqlBaseType(name)
	}
	return "", false
}

func sqliteBaseType(name string) (string, bool) {
	switch name {
	case "integer", "int":
		return "int64", true
	case "real":
		return "float64", true
	case "text", "varchar", "char":
		return "string", true
	case "blob":
		return "[]byte", true
	case "boolean", "bool":
		return "bool", true
	case "timestamp", "datetime", "date":
		return "time.Time", true
	case "numeric", "decimal":
		return "string", true
	}
	return "", false
}

func postgresBaseType(name string) (string, bool) {
	switch name {
	case "bigint", "int8", "bigserial":
		return "int64", true
	case "smallint", "int2":
		return "int16", true
	case "integer", "int", "int4", "serial":
		return "int32", true
	case "boolean", "bool":
		return "bool", true
	case "text", "varchar", "char", "bpchar", "uuid", "name":
		return "string", true
	case "double precision", "float8":
		return "float64", true
	case "real", "float4":
		return "float32", true
	case "json", "jsonb", "bytea":
		return "[]byte", true
	case "timestamp", "timestamptz", "datetime", "date":
		return "time.Time", true
	case "numeric", "decimal":
		return "string", true
	}
	return "", false
}

func mysqlBaseType(name string, length int32) (string, bool) {
	if name == "tinyint" && length == 1 {
		return "bool", true
	}
	switch name {
	case "bigint":
		return "int64", true
	case "tinyint":
		return "int16", true
	case "mediumint", "int", "integer":
		return "int32", true
	case "smallint":
		return "int16", true
	case "float":
		return "float32", true
	case "double", "double precision":
		return "float64", true
	case "decimal", "numeric":
		return "string", true
	case "datetime", "timestamp", "date":
		return "time.Time", true
	case "json":
		return "[]byte", true
	case "text", "tinytext", "mediumtext", "longtext", "char", "varchar":
		return "string", true
	case "binary", "varbinary", "tinyblob", "blob", "mediumblob", "longblob":
		return "[]byte", true
	case "boolean", "bool":
		return "bool", true
	}
	return "", false
}

func mssqlBaseType(name string) (string, bool) {
	switch name {
	case "bigint":
		return "int64", true
	case "tinyint":
		return "int16", true
	case "smallint":
		return "int16", true
	case "int":
		return "int32", true
	case "bit":
		return "bool", true
	case "real":
		return "float32", true
	case "float":
		return "float64", true
	case "decimal", "numeric", "money", "smallmoney":
		return "string", true
	case "datetime2", "smalldatetime", "datetime", "datetimeoffset", "date", "time":
		return "time.Time", true
	case "nchar", "nvarchar", "ntext", "varchar", "char", "text", "uniqueidentifier":
		return "string", true
	case "binary", "varbinary", "image":
		return "[]byte", true
	}
	return "", false
}

func (r *resolver) buildRefs(tables []catalogTable) error {
	keys := make([]string, 0, len(r.opts.Refs))
	for name := range r.opts.Refs {
		keys = append(keys, name)
	}
	sortStrings(keys)
	for _, name := range keys {
		if err := r.buildRef(name, r.opts.Refs[name] ?? "", tables); err != nil {
			return err
		}
	}
	return nil
}

func (r *resolver) buildRef(name string, target string, tables []catalogTable) error {
	parts := strings.Split(name, ".")
	if len(parts) != 2 && len(parts) != 3 {
		return fmt.Errorf("sqlc-gen-spira: refs: %q is not table.column", name)
	}
	srcName := strings.ToLower(parts[0])
	srcCol := strings.ToLower(parts[len(parts)-1])
	if len(parts) == 3 {
		if parts[0] == "" || parts[1] == "" || parts[2] == "" {
			return fmt.Errorf("sqlc-gen-spira: refs: %q is not table.column", name)
		}
		srcName = strings.ToLower(parts[0]) + "." + strings.ToLower(parts[1])
	} else if parts[0] == "" || parts[1] == "" {
		return fmt.Errorf("sqlc-gen-spira: refs: %q is not table.column", name)
	}
	srcs, err := r.findCatalogTables(srcName, tables)
	if err != nil {
		return fmt.Errorf("sqlc-gen-spira: refs.%s: %w", name, err)
	}
	src := srcs[0]
	tgts, err := r.findCatalogTables(strings.ToLower(target), tables)
	if err != nil {
		return fmt.Errorf("sqlc-gen-spira: refs.%s: %w", name, err)
	}
	tgt := tgts[0]
	tgtOpts, ok := r.optsFor(tgt)
	if !ok || tgtOpts.Key == "" {
		return fmt.Errorf("sqlc-gen-spira: refs.%s: table %s has no key", name, target)
	}
	keyCol, ok := findColumn(&tgt.table, tgtOpts.Key)
	if !ok {
		return fmt.Errorf("sqlc-gen-spira: refs.%s: key %q is not a column of %s", name, tgtOpts.Key, target)
	}
	typ, ok := r.keyed[strings.ToLower(tgt.schema)+"."+strings.ToLower(tgt.table.Rel.Name)+"."+strings.ToLower(keyCol.Name)]
	if !ok {
		return fmt.Errorf("sqlc-gen-spira: refs.%s: key column of %s has no resolved type", name, target)
	}
	if _, ok := findColumn(&src.table, srcCol); !ok {
		return fmt.Errorf("sqlc-gen-spira: refs.%s: column %q is not in %s", name, srcCol, src.table.Rel.Name)
	}
	r.refTypes[strings.ToLower(src.schema)+"."+strings.ToLower(src.table.Rel.Name)+"."+srcCol] = typ
	return nil
}

func (r *resolver) findCatalogTables(name string, tables []catalogTable) ([]catalogTable, error) {
	parts := strings.Split(strings.ToLower(name), ".")
	var matches []catalogTable
	for _, ct := range tables {
		if len(parts) == 2 {
			if strings.ToLower(ct.schema) == parts[0] && strings.ToLower(ct.table.Rel.Name) == parts[1] {
				matches = append(matches, ct)
			}
			continue
		}
		if strings.ToLower(ct.table.Rel.Name) == strings.ToLower(name) {
			matches = append(matches, ct)
		}
	}
	if len(matches) > 1 {
		var schemas []string
		for _, m := range matches {
			schemas = append(schemas, strings.ToLower(m.schema))
		}
		sortStrings(schemas)
		return nil, fmt.Errorf("table %q is ambiguous: schemas %s", name, strings.Join(schemas, ", "))
	}
	if len(matches) == 0 {
		return nil, fmt.Errorf("table %q is not in the catalog", name)
	}
	return matches, nil
}

func (r *resolver) findCatalogTable(name string, tables []catalogTable) (catalogTable, error) {
	matches, err := r.findCatalogTables(name, tables)
	if err != nil {
		return catalogTable{}, err
	}
	return matches[0], nil
}

func (r *resolver) addEntity(ct catalogTable) error {
	tname := ct.table.Rel.Name
	opts, hasOpts := r.optsFor(ct)
	if !hasOpts {
		opts = TableOpts{}
	}
	structName := opts.Type
	if structName == "" {
		structName = goName(tname)
	}
	if !isGoIdent(structName) {
		return fmt.Errorf("sqlc-gen-spira: tables.%s.type %q is not a Go identifier", tname, structName)
	}
	if err := r.claimTableType(structName, ct.schema+"."+tname); err != nil {
		return err
	}
	ent := &Entity{
		Table:   tname,
		Schema:  ct.schema,
		Struct:  structName,
		Key:     opts.Key,
		KeyType: opts.KeyType,
		Version: opts.Version,
	}
	if opts.KeyType != "" {
		colKey := strings.ToLower(ct.schema) + "." + strings.ToLower(tname) + "." + strings.ToLower(opts.Key)
		ent.KeyBase = r.keyedBase[colKey] ?? ""
	}
	seen := map[string]string{}
	for i := range ct.table.Columns {
		field, err := r.entityField(ct, &ct.table.Columns[i])
		if err != nil {
			return err
		}
		if prev, dup := seen[field.GoName]; dup {
			return fmt.Errorf("sqlc-gen-spira: %s.%s: columns %q and %q both map to field %s", ct.schema, tname, prev, field.Name, field.GoName)
		}
		seen[field.GoName] = field.Name
		ent.Fields = append(ent.Fields, field)
	}
	r.model.Entities = append(r.model.Entities, *ent)
	tnameKey := strings.ToLower(tname)
	r.byTable[tnameKey] = append(r.byTable[tnameKey] ?? []*Entity{}, &r.model.Entities[len(r.model.Entities)-1])
	return nil
}

func (r *resolver) entityField(ct catalogTable, col *Column) (Field, error) {
	if err := tagSafeName(col.Name); err != nil {
		return Field{}, fmt.Errorf("sqlc-gen-spira: %s: %w", r.columnContext(ct.schema, col), err)
	}
	goType, err := r.goColumnType(ct.schema, ct.table.Rel.Name, col)
	if err != nil {
		return Field{}, err
	}
	return Field{
		Name:    col.Name,
		GoName:  goField(col.Name),
		GoType:  goType,
		Table:   ct.table.Rel.Name,
		NotNull: col.NotNull,
	}, nil
}

func tagSafeName(name string) error {
	if strings.ContainsFunc(name, func(c rune) bool { return c == '`' || unicode.IsControl(c) }) {
		return fmt.Errorf("column name %q cannot be written into a struct tag", name)
	}
	return nil
}

func (r *resolver) columnBase(schema string, table string, col *Column) (string, error) {
	key := strings.ToLower(schema) + "." + strings.ToLower(table) + "." + strings.ToLower(col.Name)
	if typ, ok := r.refTypes[key]; ok {
		return typ, nil
	}
	if typ, ok := r.keyed[key]; ok {
		return typ, nil
	}
	return r.baseType(schema, col)
}

func (r *resolver) loadQueries(queries []Query) error {
	for i := range queries {
		qd, err := r.queryDef(&queries[i])
		if err != nil {
			return err
		}
		r.model.Queries = append(r.model.Queries, qd)
	}
	return nil
}
func (r *resolver) queryDef(q *Query) (QueryDef, error) {
	if !isCommand(q.Cmd) {
		return QueryDef{}, fmt.Errorf("sqlc-gen-spira: %s: command %s is not supported", q.Name, q.Cmd)
	}
	if r.seenQueries[q.Name] ?? false {
		return QueryDef{}, fmt.Errorf("sqlc-gen-spira: duplicate query %q", q.Name)
	}
	r.seenQueries[q.Name] = true
	qd := QueryDef{
		Name:       q.Name,
		Cmd:        q.Cmd,
		File:       q.Filename,
		Text:       q.Text,
		InsertInto: q.InsertIntoTable.Name,
	}
	if err := r.queryColumns(q, &qd); err != nil {
		return QueryDef{}, err
	}
	if err := r.queryParams(q, &qd); err != nil {
		return QueryDef{}, err
	}
	if err := r.pairSliceMarkers(q, &qd); err != nil {
		return QueryDef{}, err
	}
	if err := r.refuseVersionedWrite(q); err != nil {
		return QueryDef{}, err
	}
	if err := r.classifyRow(q, &qd); err != nil {
		return QueryDef{}, err
	}
	return qd, nil
}

func isCommand(cmd string) bool {
	switch cmd {
	case ":one", ":many", ":exec", ":execrows", ":execlastid":
		return true
	}
	return false
}

func (r *resolver) queryColumns(q *Query, qd *QueryDef) error {
	seen := map[string]bool{}
	for i := range q.Columns {
		f, err := r.queryField(q, &q.Columns[i], i)
		if err != nil {
			return err
		}
		if f.Embed == "" {
			if seen[f.GoName] ?? false {
				return fmt.Errorf("sqlc-gen-spira: query %s: duplicate Go field name %q", q.Name, f.GoName)
			}
			seen[f.GoName] = true
		}
		qd.Fields = append(qd.Fields, f)
	}
	return nil
}

func (r *resolver) queryField(q *Query, col *Column, index int) (Field, error) {
	if col.Name == "" {
		return Field{}, fmt.Errorf("sqlc-gen-spira: %s: column %d needs an alias", q.Name, index)
	}
	if err := tagSafeName(col.Name); err != nil {
		return Field{}, fmt.Errorf("sqlc-gen-spira: query %s column %d: %w", q.Name, index, err)
	}
	if col.EmbedTable.Name != "" {
		return r.embedField(q, col)
	}
	schema := r.schemaForColumn(col)
	goType, err := r.goColumnType(schema, col.Table.Name, col)
	if err != nil {
		return Field{}, fmt.Errorf("sqlc-gen-spira: query %s column %d: %w", q.Name, index, err)
	}
	return Field{
		Name:    col.Name,
		GoName:  goField(col.Name),
		GoType:  goType,
		Table:   col.Table.Name,
		NotNull: col.NotNull,
	}, nil
}

func (r *resolver) embedField(q *Query, col *Column) (Field, error) {
	st, err := r.embedStruct(q, col.EmbedTable.Name)
	if err != nil {
		return Field{}, err
	}
	return Field{
		Name:    col.Name,
		GoName:  st,
		GoType:  st,
		Table:   col.Table.Name,
		Embed:   col.EmbedTable.Name,
		NotNull: true,
	}, nil
}

func (r *resolver) schemaForColumn(col *Column) string {
	ents := r.byTable[strings.ToLower(col.Table.Name)] ?? []*Entity{}
	if len(ents) == 1 {
		return ents[0].Schema
	}
	return ""
}

func (r *resolver) queryParams(q *Query, qd *QueryDef) error {
	used := map[string]bool{}
	for i := range q.Params {
		pd, err := r.paramDef(q, &q.Params[i])
		if err != nil {
			return err
		}
		if used[pd.GoName] ?? false {
			pd.GoName = fmt.Sprintf("%s%d", pd.GoName, pd.Number)
		}
		used[pd.GoName] = true
		if pd.IsSlice {
			qd.Slices = append(qd.Slices, SliceDef{Marker: pd.Name, GoName: pd.GoName, Elem: pd.GoType})
		}
		qd.Params = append(qd.Params, pd)
	}
	if len(qd.Params) > 2 {
		qd.ArgsName = goName(q.Name) + "Args"
	}
	return nil
}

func (r *resolver) paramDef(q *Query, p *Parameter) (ParamDef, error) {
	col := p.Column
	schema := r.schemaForColumn(&col)
	goType, err := r.goColumnType(schema, col.Table.Name, &col)
	if err != nil {
		return ParamDef{}, fmt.Errorf("sqlc-gen-spira: query %s param %d: %w", q.Name, p.Number, err)
	}
	if col.IsSQLCSlice {
		goType = "[]" + goType
	}
	name := p.Name
	if name == "" {
		name = col.Name
	}
	if name == "" {
		name = fmt.Sprintf("arg%d", p.Number)
	}
	return ParamDef{
		Number:     p.Number,
		Name:       name,
		ColumnName: col.Name,
		GoName:     goField(name),
		GoType:     goType,
		IsSlice:    col.IsSQLCSlice,
	}, nil
}

func (r *resolver) pairSliceMarkers(q *Query, qd *QueryDef) error {
	markers := sliceMarkers(q.Text)
	for i := range qd.Slices {
		qd.Slices[i].Spread = hasMarker(markers, qd.Slices[i].Marker)
	}
	for _, m := range markers {
		if !hasSliceParam(qd, m) {
			return fmt.Errorf("sqlc-gen-spira: query %s: slice marker %q has no slice parameter", q.Name, m)
		}
	}
	return nil
}

func hasMarker(markers []string, name string) bool {
	for _, m := range markers {
		if m == name {
			return true
		}
	}
	return false
}

func hasSliceParam(qd *QueryDef, name string) bool {
	for i := range qd.Slices {
		if qd.Slices[i].Marker == name {
			return true
		}
	}
	return false
}

func sliceMarkers(text string) []string {
	var out []string
	rest := text
	for {
		start := strings.Index(rest, "/*SLICE:")
		if start < 0 {
			return out
		}
		rest = rest[start+len("/*SLICE:"):]
		end := strings.Index(rest, "*/?")
		if end < 0 {
			return out
		}
		out = append(out, rest[:end])
		rest = rest[end+len("*/?"):]
	}
}

func (r *resolver) refuseVersionedWrite(q *Query) error {
	upper := strings.ToUpper(maskSQLFor(r.engine, q.Text))
	for _, target := range writeTargets(upper) {
		versioned, ok := r.versions[strings.ToLower(target)]
		if !ok || versioned.version == "" {
			continue
		}
		if !strings.Contains(upper, strings.ToUpper(versioned.version)) {
			return fmt.Errorf("sqlc-gen-spira: %s: writes versioned table %s without %s", q.Name, versioned.name, versioned.version)
		}
	}
	return nil
}

// maskSQLFor blanks string literals and comments so the write scan sees
// statements, not text. Quoted identifiers stay: they may name columns.
// A backslash escapes the next character only in literal forms that support
// it: MySQL strings and PostgreSQL escape strings. Everywhere else the
// backslash is an ordinary character, so the literal ends at its quote.
// PostgreSQL continuation segments keep the first segment's escape mode.
func maskSQLFor(engine string, text string) string {
	out := []byte(text)
	i := 0
	for i < len(out) {
		i = maskAtFor(out, i, engine)
	}
	return string(out)
}

func maskAtFor(out []byte, i int, engine string) int {
	if out[i] == '\'' {
		return maskStringFor(out, i, engine)
	}
	if out[i] == '-' && i+1 < len(out) && out[i+1] == '-' {
		return maskLine(out, i)
	}
	if out[i] == '/' && i+1 < len(out) && out[i+1] == '*' {
		return maskBlock(out, i)
	}
	return i + 1
}

func maskStringFor(out []byte, i int, engine string) int {
	escape := backslashEscapes(engine, out, i)
	for {
		end := maskQuotedFor(out, i, escape)
		if engine != "postgresql" {
			return end
		}
		next := postgresContinuedQuote(out, end)
		if next == nil {
			return end
		}
		blank(out, end, next)
		i = next
	}
}

func postgresContinuedQuote(out []byte, i int) int? {
	newline := false
	for i < len(out) {
		if out[i] == '-' && i+1 < len(out) && out[i+1] == '-' {
			i = postgresLineEnd(out, i+2)
			continue
		}
		switch out[i] {
		case '\r', '\n':
			newline = true
		case ' ', '\t', '\f', '\v':
		default:
			if newline && out[i] == '\'' {
				return i
			}
			return nil
		}
		i++
	}
	return nil
}

func postgresLineEnd(out []byte, i int) int {
	for i < len(out) && out[i] != '\r' && out[i] != '\n' {
		i++
	}
	return i
}

func backslashEscapes(engine string, out []byte, i int) bool {
	if engine == "mysql" {
		return true
	}
	if engine == "postgresql" && i > 0 && (out[i-1] == 'E' || out[i-1] == 'e') {
		return true
	}
	return false
}

func maskQuotedFor(out []byte, i int, escape bool) int {
	j := i + 1
	for j < len(out) {
		if escape && out[j] == '\\' && j+1 < len(out) {
			j += 2
			continue
		}
		if out[j] == '\'' {
			if j+1 < len(out) && out[j+1] == '\'' {
				j += 2
				continue
			}
			j++
			break
		}
		j++
	}
	blank(out, i, j)
	return j
}

 func maskLine(out []byte, i int) int {
 	j := i + 2
 	for j < len(out) && out[j] != '\n' {
 		j++
 	}
 	blank(out, i, j)
 	return j
 }

 func maskBlock(out []byte, i int) int {
 	j := i + 2
 	for j+1 < len(out) && !(out[j] == '*' && out[j+1] == '/') {
 		j++
 	}
 	if j+1 < len(out) {
 		j += 2
 	} else {
 		j = len(out)
 	}
 	blank(out, i, j)
 	return j
 }

 func blank(out []byte, from int, to int) {
 	for k := from; k < to; k++ {
 		out[k] = ' '
 	}
 }

func writeTargets(upper string) []string {
	var out []string
	out = append(out, updateTargets(upper)...)
	out = append(out, deleteTargets(upper)...)
	return out
}

func updateTargets(upper string) []string {
	var out []string
	pos := 0
	for {
		found := keywordAt(upper, pos, "UPDATE")
		if found < 0 {
			return out
		}
		rest := skipSpaces(upper[found+len("UPDATE"):])
		if target, ok := firstWord(rest); ok {
			out = append(out, target)
		}
		pos = found + len("UPDATE")
	}
}

func deleteTargets(upper string) []string {
	var out []string
	pos := 0
	for {
		found := keywordAt(upper, pos, "DELETE")
		if found < 0 {
			return out
		}
		rest := skipSpaces(upper[found+len("DELETE"):])
		after, ok := cutWord(rest, "FROM")
		if !ok {
			pos = found + len("DELETE")
			continue
		}
		rest = skipSpaces(after)
		if target, ok := firstWord(rest); ok {
			out = append(out, target)
		}
		pos = found + len("DELETE")
	}
}

func keywordAt(upper string, pos int, word string) int {
	offset := 0
	for {
		search := upper[pos+offset:]
		idx := strings.Index(search, word)
		if idx < 0 {
			return -1
		}
		abs := pos + offset + idx
		if isWordBoundary(upper, abs, len(word)) {
			return abs
		}
		offset += idx + len(word)
	}
}

func isWordBoundary(s string, pos int, length int) bool {
	if pos > 0 && isWordChar(s[pos-1]) {
		return false
	}
	if pos+length < len(s) && isWordChar(s[pos+length]) {
		return false
	}
	return true
}

func isWordChar(c byte) bool {
	if c == '_' {
		return true
	}
	if c >= 'A' && c <= 'Z' {
		return true
	}
	if c >= '0' && c <= '9' {
		return true
	}
	return false
}

func skipSpaces(s string) string {
	i := 0
	for i < len(s) {
		c := s[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		break
	}
	if i == 0 {
		return s
	}
	return s[i:]
}

func cutWord(s string, word string) (string, bool) {
	if len(s) < len(word) {
		return "", false
	}
	if s[:len(word)] != word {
		return "", false
	}
	if len(s) > len(word) && isWordChar(s[len(word)]) {
		return "", false
	}
	return s[len(word):], true
}

func firstWord(s string) (string, bool) {
	end := strings.IndexAny(s, " \t\n\r;")
	word := s
	if end >= 0 {
		word = s[:end]
	}
	if i := strings.LastIndex(word, "."); i >= 0 {
		word = word[i+1:]
	}
	return word, word != ""
}

func (r *resolver) buildVersions(tables []catalogTable) error {
	keys := make([]string, 0, len(r.opts.Tables))
	for name := range r.opts.Tables {
		keys = append(keys, name)
	}
	sortStrings(keys)
	for _, name := range keys {
		version := (r.opts.Tables[name] ?? TableOpts{}).Version
		if version == "" {
			continue
		}
		ct, err := r.findCatalogTable(name, tables)
		if err != nil {
			return fmt.Errorf("sqlc-gen-spira: tables.%s: %w", name, err)
		}
		key := strings.ToLower(ct.table.Rel.Name)
		if _, dup := r.versions[key]; !dup {
			r.versions[key] = tableVersion{name: ct.table.Rel.Name, version: version}
		}
	}
	return nil
}

func (r *resolver) classifyRow(q *Query, qd *QueryDef) error {
	for i := range qd.Fields {
		if qd.Fields[i].Embed != "" {
			return r.classifyEmbed(q, qd)
		}
	}
	if len(qd.Fields) == 1 {
		qd.RowGoType = qd.Fields[0].GoType
		return nil
	}
	if name, ok := r.matchEntity(qd); ok {
		qd.RowGoType = name
		return nil
	}
	qd.RowGoType = goName(q.Name) + "Row"
	return nil
}

func (r *resolver) classifyEmbed(q *Query, qd *QueryDef) error {
	qd.RowGoType = goName(q.Name) + "Row"
	flat := map[string]bool{}
	for i := range qd.Fields {
		if qd.Fields[i].Embed == "" {
			flat[qd.Fields[i].GoName] = true
		}
	}
	seen := map[string]bool{}
	for i := range qd.Fields {
		table := qd.Fields[i].Embed
		if table == "" {
			continue
		}
		key := strings.ToLower(table)
		if seen[key] ?? false {
			continue
		}
		seen[key] = true
		st, err := r.embedStruct(q, table)
		if err != nil {
			return err
		}
		if flat[st] ?? false {
			return fmt.Errorf("sqlc-gen-spira: query %s: embed field %q collides with a column field", q.Name, st)
		}
		flat[st] = true
		qd.Embeds = append(qd.Embeds, EmbedDef{Table: table, Field: st, Struct: st})
	}
	return nil
}

func (r *resolver) embedStruct(q *Query, table string) (string, error) {
	ents := r.byTable[strings.ToLower(table)] ?? []*Entity{}
	if len(ents) == 0 {
		return "", fmt.Errorf("sqlc-gen-spira: query %s: embed table %q is not in the catalog", q.Name, table)
	}
	if len(ents) > 1 {
		return "", fmt.Errorf("sqlc-gen-spira: query %s: embed table %q is ambiguous", q.Name, table)
	}
	return ents[0].Struct, nil
}

func (r *resolver) matchEntity(qd *QueryDef) (string, bool) {
	for i := range r.model.Entities {
		if entityMatches(&r.model.Entities[i], qd) {
			return r.model.Entities[i].Struct, true
		}
	}
	return "", false
}

func entityMatches(e *Entity, qd *QueryDef) bool {
	if len(e.Fields) != len(qd.Fields) {
		return false
	}
	for i := range e.Fields {
		if e.Fields[i].Name != qd.Fields[i].Name {
			return false
		}
		if !strings.EqualFold(qd.Fields[i].Table, e.Table) {
			return false
		}
	}
	return true
}

func (r *resolver) goColumnType(schema string, table string, col *Column) (string, error) {
	base, err := r.columnBase(schema, table, col)
	if err != nil {
		return "", err
	}
	if col.NotNull {
		return base, nil
	}
	if r.isKeyed(schema, table, col) {
		under, uerr := r.baseType(schema, col)
		if uerr != nil {
			return "", uerr
		}
		return under + "?", nil
	}
	return base + "?", nil
}

func (r *resolver) isKeyed(schema string, table string, col *Column) bool {
	key := strings.ToLower(schema) + "." + strings.ToLower(table) + "." + strings.ToLower(col.Name)
	if _, ok := r.refTypes[key]; ok {
		return true
	}
	if _, ok := r.keyed[key]; ok {
		return true
	}
	return false
}

package db

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"log/slog"
	"logos/sync"
	"net/url"
	"strconv"
	"strings"
	"time"
)

type Querier interface {
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows?, error)
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
}

type SQLite struct{}

type Postgres struct{}

type MySQL struct{}

type MSSQL struct{}

type Dialect interface {
	SQLite | Postgres | MySQL | MSSQL
}

const skipCache = "/*db:nocache*/"

func DialectOf(driver string, dsn string) (Dialect, error) {
	switch driver {
	case "sqlite":
		return SQLite{}, nil
	case "pgx", "postgres":
		return Postgres{}, nil
	case "mysql":
		value, found := dsnParam(mysqlQueryPart(dsn), "parseTime")
		if !found || !parseTimeOn(value) {
			return nil, ErrMissingParseTime.Wrap(errors.New("db: mysql DSN needs parseTime=true"))
		}
		return MySQL{}, nil
	case "sqlserver":
		return MSSQL{}, nil
	default:
		return nil, ErrUnknownDriver.Wrap(fmt.Errorf("db: unknown driver %q", driver))
	}
}

func mysqlQueryPart(dsn string) string {
	tail := dsn[strings.LastIndexByte(dsn, '/')+1:]
	if q := strings.IndexByte(tail, '?'); q >= 0 {
		return tail[q+1:]
	}
	return ""
}

func dsnParam(query string, key string) (string, bool) {
	for query != "" {
		var pair string
		pair, query, _ = strings.Cut(query, "&")
		name, value, ok := strings.Cut(pair, "=")
		if ok && name == key {
			return value, true
		}
	}
	return "", false
}

func parseTimeOn(value string) bool {
	return strings.EqualFold(value, "true") || value == "1" || value == "t" || value == "T"
}

type PoolOptions struct {
	MaxOpenConns    int
	MaxIdleConns    int
	ConnMaxLifetime time.Duration
	ConnMaxIdleTime time.Duration
}

func poolDefaults(d Dialect) PoolOptions {
	switch d.(type) {
	case SQLite:
		return PoolOptions{MaxOpenConns: 4, MaxIdleConns: 2, ConnMaxLifetime: 30 * time.Minute, ConnMaxIdleTime: 5 * time.Minute}
	case Postgres, MySQL, MSSQL:
		return PoolOptions{MaxOpenConns: 10, MaxIdleConns: 5, ConnMaxLifetime: 30 * time.Minute, ConnMaxIdleTime: 5 * time.Minute}
	case nil:
	}
	panic("db: unknown dialect for pool defaults")
}

// firstSetPoolOptions merges every option set: each field comes from the
// first set that leaves it nonzero, so later sets fill the gaps of the
// earlier ones instead of being ignored.
func firstSetPoolOptions(opts []PoolOptions) PoolOptions {
	merged := PoolOptions{}
	for _, o := range opts {
		if merged.MaxOpenConns == 0 {
			merged.MaxOpenConns = o.MaxOpenConns
		}
		if merged.MaxIdleConns == 0 {
			merged.MaxIdleConns = o.MaxIdleConns
		}
		if merged.ConnMaxLifetime == 0 {
			merged.ConnMaxLifetime = o.ConnMaxLifetime
		}
		if merged.ConnMaxIdleTime == 0 {
			merged.ConnMaxIdleTime = o.ConnMaxIdleTime
		}
	}
	return merged
}

func resolvePoolOptions(d Dialect, dsn string, opts []PoolOptions) PoolOptions {
	defaults := poolDefaults(d)
	merged := firstSetPoolOptions(opts)
	if merged.MaxOpenConns == 0 {
		merged.MaxOpenConns = defaults.MaxOpenConns
	}
	if merged.MaxIdleConns == 0 {
		merged.MaxIdleConns = defaults.MaxIdleConns
	}
	if merged.ConnMaxLifetime == 0 {
		merged.ConnMaxLifetime = defaults.ConnMaxLifetime
	}
	if merged.ConnMaxIdleTime == 0 {
		merged.ConnMaxIdleTime = defaults.ConnMaxIdleTime
	}
	if isInMemorySQLite(d, dsn) {
		merged.ConnMaxLifetime = 0
		merged.ConnMaxIdleTime = 0
		if merged.MaxIdleConns < 1 {
			merged.MaxIdleConns = 1
		}
	}
	return merged
}

// isInMemorySQLite reports whether the SQLite DSN names an in-memory
// database. Closing the last connection to one deletes it, so the pool
// must never evict its final physical connection.
func isInMemorySQLite(d Dialect, dsn string) bool {
	if _, ok := d.(SQLite); !ok {
		return false
	}
	name, _, _ := strings.Cut(dsn, "?")
	if name == ":memory:" {
		return true
	}
	uri, ok := strings.CutPrefix(dsn, "file:")
	if !ok {
		return false
	}
	uri, _, _ = strings.Cut(uri, "#")
	name, query, _ := strings.Cut(uri, "?")
	if path, err := url.PathUnescape(name); err == nil && path == ":memory:" {
		return true
	}
	params, err := url.ParseQuery(query)
	if err != nil {
		return false
	}
	return params.Get("mode") == "memory"
}

func applyPoolLimits(handle *sql.DB, opts PoolOptions) {
	handle.SetMaxOpenConns(opts.MaxOpenConns)
	handle.SetMaxIdleConns(opts.MaxIdleConns)
	handle.SetConnMaxLifetime(opts.ConnMaxLifetime)
	handle.SetConnMaxIdleTime(opts.ConnMaxIdleTime)
}

func Open(driver string, dsn string, opts ...PoolOptions) (*Pool?, error) {
	dialect, err := DialectOf(driver, dsn)
	if err != nil {
		return nil, err
	}
	handle, err := sql.Open(driver, dsn)
	if err != nil {
		return nil, ClassifyDriverError(dialect, fmt.Errorf("db: open %s: %w", driver, err))
	}
	applyPoolLimits(handle, resolvePoolOptions(dialect, dsn, opts))
	return &Pool{handle: handle, dialect: dialect, stmts: &stmtCache{}, migSem: make(chan struct{}, 1)}, nil
}

// OpenSQLiteImmediate opens a SQLite pool whose writable transactions begin
// with a writer reservation. Use InSQLiteImmediateTx to require that mode.
func OpenSQLiteImmediate(dsn string, opts ...PoolOptions) (*Pool?, error) {
	configured := sqliteImmediateDSN(dsn)?
	pool := Open("sqlite", configured, opts...)?
	if pool == nil {
		return nil, ErrStatementFailed.Wrap(errors.New("db: SQLite open returned no pool"))
	}
	pool.sqliteImmediate = true
	return pool, nil
}

func sqliteImmediateDSN(dsn string) (string, error) {
	name, query, _ := strings.Cut(dsn, "?")
	if name == "" || strings.ContainsRune(dsn, 0) {
		return "", errors.New("db: SQLite immediate transactions require a database name")
	}
	params, err := url.ParseQuery(query)
	if err != nil {
		return "", errors.New("db: invalid SQLite DSN query")
	}
	if params.Has("vfs") || params.Has("nolock") || params.Has("immutable") {
		return "", errors.New("db: SQLite immediate transactions require the default locking VFS")
	}
	mode, _ := params["mode"]
	cache, _ := params["cache"]
	if len(mode) > 1 || len(cache) > 1 {
		return "", errors.New("db: ambiguous SQLite URI mode or cache")
	}
	if err := checkSQLiteDatabaseName(dsn, name, params.Get("mode"), params.Get("cache")); err != nil {
		return "", err
	}
	configured := name + "?_txlock=immediate"
	if query != "" {
		configured += "&" + query
	}
	return configured, nil
}

func checkSQLiteDatabaseName(dsn string, name string, mode string, cache string) error {
	if name == ":memory:" {
		return errors.New("db: SQLite immediate transactions require a shared in-memory database")
	}
	path, uri := strings.CutPrefix(name, "file:")
	if !uri {
		return nil
	}
	if strings.ContainsRune(dsn, '#') || strings.Contains(dsn, "%00") {
		return errors.New("db: SQLite immediate transactions do not accept URI fragments or encoded NULs")
	}
	path, err := url.PathUnescape(path)
	if err != nil {
		return errors.New("db: invalid SQLite URI path")
	}
	if path == "" || path == "//localhost" {
		return errors.New("db: SQLite immediate transactions require a database name")
	}
	if (path == ":memory:" || mode == "memory") && cache != "shared" {
		return errors.New("db: SQLite immediate transactions require a shared in-memory database")
	}
	return nil
}

 type Pool struct {
 	handle          *sql.DB
 	dialect         Dialect
 	stmts           *stmtCache
 	sqliteImmediate bool
 	migSem          chan struct{}
 }
 func (p *Pool) Dialect() Dialect {
 	return p.dialect
 }

// AcquireMigrationTurn takes the pool's migration turn. Release it with the
// returned function, which frees the turn only once. A done context fails
// instead of queueing behind a turn that another migration holds, and an
// already-ended context fails even when the turn is free.
func (p *Pool) AcquireMigrationTurn(ctx context.Context) (func(), error) {
	if err := ctx.Err(); err != nil {
		return nil, fmt.Errorf("db: wait for migration turn: %w", err)
	}
	select {
	case p.migSem <- struct{}{}:
		if err := ctx.Err(); err != nil {
			select {
			case <-p.migSem:
			default:
			}
			return nil, fmt.Errorf("db: wait for migration turn: %w", err)
		}
		var used sync.Locked[bool]
		return func() {
			used.WithLock(func(released *bool) {
				if *released {
					return
				}
				*released = true
				select {
				case <-p.migSem:
				default:
				}
			})
		}, nil
	case <-ctx.Done():
		return nil, fmt.Errorf("db: wait for migration turn: %w", ctx.Err())
	}
}

func (p *Pool) Prepared() int {
	return p.stmts.size()
}

func (p *Pool) Stats() sql.DBStats {
	return p.handle.Stats()
}

func (p *Pool) Prepare(ctx context.Context, query string) error {
	q, skip := unmarked(query)
	if skip {
		return ClassifyDriverError(p.dialect, prepareDirect(ctx, p.handle, q))
	}
	if _, cached := p.stmts.acquire(q); cached {
		p.stmts.release(q)
		return ClassifyDriverError(p.dialect, prepareDirect(ctx, p.handle, q))
	}
	stmt, err := p.stmts.prepare(ctx, p.handle, q)
	if err != nil {
		return ClassifyDriverError(p.dialect, err)
	}
	if stmt == nil {
		return ErrStatementFailed.Wrap(errors.New("db: prepared statement missing"))
	}
	p.stmts.release(q)
	return nil
}

func prepareDirect(ctx context.Context, handle *sql.DB, q string) error {
	stmt, err := handle.PrepareContext(ctx, q)
	if err != nil {
		return fmt.Errorf("db: prepare: %w", err)
	}
	if cerr := stmt.Close(); cerr != nil {
		return fmt.Errorf("db: prepare close: %w", cerr)
	}
	return nil
}

func (p *Pool) Start(ctx context.Context) error {
	if err := p.handle.PingContext(ctx); err != nil {
		return ClassifyDriverError(p.dialect, fmt.Errorf("db: ping: %w", err))
	}
	return nil
}

func (p *Pool) Stop(ctx context.Context) error {
	run := &poolClose{done: make(chan struct{})}
	joinCtx, joinCancel := context.WithCancel(context.Background())
	context.AfterFunc(joinCtx, func() {
		p.closeAll(run)
	})
	joinCancel()
	select {
	case <-run.done:
	case <-ctx.Done():
		return ClassifyDriverError(p.dialect, fmt.Errorf("db: stop: %w", ctx.Err()))
	}
	var err error
	run.err.WithLock(func(e *error) {
		err = *e
	})
	return err
}

type poolClose struct {
	err  sync.Locked[error]
	done chan struct{}
}

func (p *Pool) closeAll(run *poolClose) {
	stmtErr := p.stmts.closeStmts()
	handleErr := p.handle.Close()
	var result error
	if handleErr != nil {
		result = ClassifyDriverError(p.dialect, fmt.Errorf("db: close: %w", errors.Join(stmtErr, handleErr)))
	} else {
		result = ClassifyDriverError(p.dialect, stmtErr)
	}
	run.err.WithLock(func(e *error) {
		*e = result
	})
	close(run.done)
}

func (p *Pool) QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows?, error) {
	q, skip := unmarked(query)
	if skip {
		rows, err := p.handle.QueryContext(ctx, q, args...)
		if err != nil {
			return nil, ClassifyDriverError(p.dialect, fmt.Errorf("db: query: %w", err))
		}
		return rows, nil
	}
	prepared, err := p.stmts.prepare(ctx, p.handle, q)
	if err != nil {
		return nil, ClassifyDriverError(p.dialect, err)
	}
	if prepared == nil {
		return nil, ErrStatementFailed.Wrap(errors.New("db: prepared statement missing"))
	}
	rows, err := prepared.QueryContext(ctx, args...)
	p.stmts.release(q)
	if err != nil {
		return nil, ClassifyDriverError(p.dialect, fmt.Errorf("db: query: %w", err))
	}
	if rows == nil {
		return nil, ErrStatementFailed.Wrap(errors.New("db: query returned no rows"))
	}
	return rows, nil
}

func (p *Pool) ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error) {
	q, skip := unmarked(query)
	if skip {
		res, err := p.handle.ExecContext(ctx, q, args...)
		if err != nil {
			return nil, ClassifyDriverError(p.dialect, fmt.Errorf("db: exec: %w", err))
		}
		return res, nil
	}
	prepared, err := p.stmts.prepare(ctx, p.handle, q)
	if err != nil {
		return nil, ClassifyDriverError(p.dialect, err)
	}
	if prepared == nil {
		return nil, ErrStatementFailed.Wrap(errors.New("db: prepared statement missing"))
	}
	res, err := prepared.ExecContext(ctx, args...)
	p.stmts.release(q)
	if err != nil {
		return nil, ClassifyDriverError(p.dialect, fmt.Errorf("db: exec: %w", err))
	}
	return res, nil
}

type Tx struct {
	tx   *sql.Tx
	pool *Pool
}

func (t *Tx) QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows?, error) {
	q, skip := unmarked(query)
	if skip {
		rows, err := t.tx.QueryContext(ctx, q, args...)
		if err != nil {
			return nil, ClassifyDriverError(t.pool.dialect, fmt.Errorf("db: query: %w", err))
		}
		return rows, nil
	}
	if stmt, cached := t.pool.stmts.acquire(q); cached {
		rows, err := t.tx.StmtContext(ctx, stmt).QueryContext(ctx, args...)
		t.pool.stmts.release(q)
		if err != nil {
			return nil, ClassifyDriverError(t.pool.dialect, fmt.Errorf("db: query: %w", err))
		}
		if rows == nil {
			return nil, ErrStatementFailed.Wrap(errors.New("db: query returned no rows"))
		}
		return rows, nil
	}
	rows, err := t.tx.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, ClassifyDriverError(t.pool.dialect, fmt.Errorf("db: query: %w", err))
	}
	if rows == nil {
		return nil, ErrStatementFailed.Wrap(errors.New("db: query returned no rows"))
	}
	return rows, nil
}

func (t *Tx) ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error) {
	q, skip := unmarked(query)
	if skip {
		res, err := t.tx.ExecContext(ctx, q, args...)
		if err != nil {
			return nil, ClassifyDriverError(t.pool.dialect, fmt.Errorf("db: exec: %w", err))
		}
		return res, nil
	}
	if stmt, cached := t.pool.stmts.acquire(q); cached {
		res, err := t.tx.StmtContext(ctx, stmt).ExecContext(ctx, args...)
		t.pool.stmts.release(q)
		if err != nil {
			return nil, ClassifyDriverError(t.pool.dialect, fmt.Errorf("db: exec: %w", err))
		}
		return res, nil
	}
	res, err := t.tx.ExecContext(ctx, q, args...)
	if err != nil {
		return nil, ClassifyDriverError(t.pool.dialect, fmt.Errorf("db: exec: %w", err))
	}
	return res, nil
}

func InTx[T any](ctx context.Context, p *Pool, work func(tx *Tx) (T, error)) (T, error) {
	var zero T
	tx, err := p.handle.BeginTx(ctx, &sql.TxOptions{})
	if err != nil {
		return zero, ClassifyDriverError(p.dialect, fmt.Errorf("db: begin: %w", err))
	}
	return finishTx(ctx, &Tx{tx: tx, pool: p}, work)
}

// InSQLiteImmediateTx requires a writer reservation before calling work.
func InSQLiteImmediateTx[T any](ctx context.Context, p *Pool, work func(tx *Tx) (T, error)) (value T, err error) {
	var zero T
	if !p.sqliteImmediate {
		return zero, ErrStatementFailed.Wrap(errors.New("db: SQLite immediate transaction requires an immediate SQLite pool"))
	}
	conn, err := p.handle.Conn(ctx)
	if err != nil {
		return zero, ClassifyDriverError(p.dialect, fmt.Errorf("db: lease SQLite connection: %w", err))
	}
	if conn == nil {
		return zero, ErrStatementFailed.Wrap(errors.New("db: SQLite lease returned no connection"))
	}
	defer closeSQLiteConn(conn)?
	var busyMillis int
	if err := conn.QueryRowContext(ctx, "PRAGMA busy_timeout").Scan(&busyMillis); err != nil {
		return zero, ClassifyDriverError(p.dialect, fmt.Errorf("db: read SQLite busy timeout: %w", err))
	}
	const writerBusyMillis = 30000
	if busyMillis != writerBusyMillis {
		defer restoreSQLiteBusyTimeout(ctx, conn, busyMillis, &err)
		if _, err := conn.ExecContext(ctx, "PRAGMA busy_timeout = "+strconv.Itoa(writerBusyMillis)); err != nil {
			return zero, ClassifyDriverError(p.dialect, fmt.Errorf("db: set SQLite busy timeout: %w", err))
		}
	}
	tx, err := conn.BeginTx(ctx, &sql.TxOptions{})
	if err != nil {
		return zero, ClassifyDriverError(p.dialect, fmt.Errorf("db: begin immediate: %w", err))
	}
	return finishTx(ctx, &Tx{tx: tx, pool: p}, func(run *Tx) (T, error) {
		requireSQLiteRollback(ctx, tx)?
		return work(run)
	})
}

func requireSQLiteRollback(ctx context.Context, tx *sql.Tx) error {
	var journalMode string
	row := tx.QueryRowContext(ctx, "PRAGMA main.journal_mode")
	if err := row.Scan(&journalMode); err != nil {
		return ClassifyDriverError(SQLite{}, fmt.Errorf("db: read SQLite journal mode: %w", err))
	}
	if journalMode == "off" {
		return ErrStatementFailed.Wrap(errors.New("db: SQLite immediate transactions require rollback journaling"))
	}
	return nil
}

func restoreSQLiteBusyTimeout(ctx context.Context, conn *sql.Conn, millis int, outcome *error) {
	cleanup, cancel := context.WithTimeout(context.WithoutCancel(ctx), time.Second)
	defer cancel()
	_, err := conn.ExecContext(cleanup, "PRAGMA busy_timeout = "+strconv.Itoa(millis))
	if err == nil || errors.Is(err, sql.ErrConnDone) {
		return
	}
	restoreErr := fmt.Errorf("db: restore SQLite busy timeout: %w", err)
	discardErr := conn.Raw(func(_ any) error { return driver.ErrBadConn })
	if !errors.Is(discardErr, driver.ErrBadConn) && !errors.Is(discardErr, sql.ErrConnDone) {
		restoreErr = errors.Join(restoreErr, fmt.Errorf("db: discard SQLite connection: %w", discardErr))
	}
	if *outcome != nil {
		*outcome = errors.Join(*outcome, restoreErr)
		return
	}
	slog.Error("db: SQLite connection cleanup after immediate transaction", "error", restoreErr)
}

func closeSQLiteConn(conn *sql.Conn) error {
	err := conn.Close()
	if errors.Is(err, sql.ErrConnDone) {
		return nil
	}
	return err
}

func finishTx[T any](ctx context.Context, run *Tx, work func(tx *Tx) (T, error)) (T, error) {
	var zero T
	v, workErr := runTxWork(run, work)
	if workErr != nil {
		return zero, workErr
	}
	if err := ctx.Err(); err != nil {
		// The caller is gone: report the context cause itself. A rollback
		// the driver already performed surfaces as sql.ErrTxDone and must
		// not join the cause; only a genuine rollback failure joins it.
		if rerr := run.tx.Rollback(); rerr != nil && !errors.Is(rerr, sql.ErrTxDone) {
			return zero, errors.Join(err, rerr)
		}
		return zero, err
	}
	if err := run.tx.Commit(); err != nil {
		return zero, ClassifyDriverError(run.pool.dialect, fmt.Errorf("db: commit: %w", err))
	}
	return v, nil
}

func runTxWork[T any](run *Tx, work func(tx *Tx) (T, error)) (T, error) {
	errdefer run.tx.Rollback()?
	return work(run)
}

func Exec(ctx context.Context, q Querier, query string, args ...any) (sql.Result, error) {
	return q.ExecContext(ctx, query, args...)
}

func In(query string, name string, count int) string {
	expanded := strings.Replace(query, marker(name), replacement(count), 1)
	return skipCache + expanded
}

func marker(name string) string {
	return "/*SLICE:" + name + "*/?"
}

func replacement(count int) string {
	if count <= 0 {
		return "NULL"
	}
	var b strings.Builder
	for i := range count {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("?")
	}
	return b.String()
}

func unmarked(query string) (string, bool) {
	if strings.HasPrefix(query, skipCache) {
		return strings.TrimPrefix(query, skipCache), true
	}
	return query, false
}

package migrate_test

import (
	"context"
	"errors"
	"slices"
	"logos/sync"
	"testing"
	"time"

	"github.com/gosuda/spira/migrate"
)

func TestApplyWithCancelledContextChangesNothing(t *testing.T) {
	pool := openPool(t)
	steps := []migrate.Step{
		{Name: "0001_cancelled", Up: "CREATE TABLE cancelled_apply (n integer);", Down: "DROP TABLE cancelled_apply;"},
	}
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if err := migrate.Apply(ctx, pool, steps); err == nil {
		t.Fatal("Apply with a cancelled context succeeded; want the context error")
		return
	}
	if names := tableNames(t, pool); slices.Contains(names, "cancelled_apply") {
		t.Fatalf("tables after cancelled Apply = %v; want no cancelled_apply", names)
	}
}

func TestMigrationSerialIsPerPool(t *testing.T) {
	first := openPool(t)
	second := openPool(t)
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	release, err := first.AcquireMigrationTurn(ctx)
	if err != nil {
		t.Fatalf("hold first pool turn: %v", err)
		return
	}
	defer release()
	other, err := second.AcquireMigrationTurn(ctx)
	if err != nil {
		t.Fatalf("second pool turn: %v; want no wait on another pool", err)
		return
	}
	defer other()
}

func TestMigrationTurnHonorsCancel(t *testing.T) {
	pool := openPool(t)
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	release, err := pool.AcquireMigrationTurn(ctx)
	if err != nil {
		t.Fatalf("hold pool turn: %v", err)
		return
	}
	defer release()
	cancelled, stop := context.WithCancel(t.Context())
	stop()
	if _, err := pool.AcquireMigrationTurn(cancelled); err == nil {
		t.Fatal("AcquireMigrationTurn with a cancelled context succeeded; want the context error")
		return
	}
}

func TestQueuedApplyHonorsContext(t *testing.T) {
	pool := openPool(t)
	steps := []migrate.Step{
		{Name: "0001_queued", Up: "CREATE TABLE queued_apply (n integer);", Down: "DROP TABLE queued_apply;"},
	}
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	release, err := pool.AcquireMigrationTurn(ctx)
	if err != nil {
		t.Fatalf("hold pool turn: %v", err)
		return
	}
	defer release()
	applyCtx, stop := context.WithTimeout(t.Context(), 200*time.Millisecond)
	defer stop()
	done := make(chan error, 1)
	finished := make(chan struct{})
	var watchdogFired sync.Locked[bool]
	run := func() error {
		go group (t.Context(), limit = 2) {
			go {
				defer close(finished)
				done <- migrate.Apply(applyCtx, pool, steps)
			}
			go {
				watchdog := time.NewTimer(5 * time.Second)
				defer watchdog.Stop()
				select {
				case <-finished:
				case <-watchdog.C:
					watchdogFired.WithLock(func(fired *bool) { *fired = true })
					release()
				}
			}
		}
		return nil
	}
	if err := run(); err != nil {
		t.Fatalf("group: %v", err)
		return
	}
	fired := false
	watchdogFired.WithLock(func(value *bool) { fired = *value })
	select {
	case err := <-done:
		if fired {
			t.Fatal("queued Apply ignored its context deadline; the watchdog freed the turn")
			return
		}
		if err == nil {
			t.Fatal("queued Apply succeeded past its context deadline; want the context error")
			return
		}
		if !errors.Is(err, context.DeadlineExceeded) {
			t.Fatalf("queued Apply err = %v; want context deadline exceeded", err)
			return
		}
	case <-time.After(5 * time.Second):
		t.Fatal("queued Apply ignored its context deadline")
	}
	if names := tableNames(t, pool); slices.Contains(names, "queued_apply") {
		t.Fatalf("tables after queued Apply = %v; want no queued_apply", names)
	}
}

func TestReleaseFreesTheTurnOnlyOnce(t *testing.T) {
	pool := openPool(t)
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	releaseA, err := pool.AcquireMigrationTurn(ctx)
	if err != nil {
		t.Fatalf("first acquire: %v", err)
		return
	}
	releaseA()
	releaseB, err := pool.AcquireMigrationTurn(ctx)
	if err != nil {
		t.Fatalf("second acquire: %v", err)
		return
	}
	releaseA()
	probe, stop := context.WithTimeout(t.Context(), 100*time.Millisecond)
	defer stop()
	if _, err := pool.AcquireMigrationTurn(probe); err == nil {
		t.Fatal("a repeated release freed another migration turn; want the second turn to stay held")
		return
	} else if !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("probe acquire err = %v; want context deadline exceeded", err)
		return
	}
	releaseB()
}

func TestMigrationTurnRejectsEndedContextOnFreePool(t *testing.T) {
	pool := openPool(t)
	cancelled, stop := context.WithCancel(t.Context())
	stop()
	if _, err := pool.AcquireMigrationTurn(cancelled); err == nil {
		t.Fatal("AcquireMigrationTurn with a cancelled context on a free pool succeeded; want the context error")
		return
	} else if !errors.Is(err, context.Canceled) {
		t.Fatalf("free-pool acquire err = %v; want context canceled", err)
		return
	}
}

func TestRollbackZeroSkipsTheTurn(t *testing.T) {
	pool := openPool(t)
	steps := loadSteps(t, "good")
	before := sqliteSchemaSnapshot(t, pool)
	held, err := pool.AcquireMigrationTurn(t.Context())
	if err != nil {
		t.Fatalf("hold pool turn: %v", err)
		return
	}
	defer held()
	cancelled, stop := context.WithCancel(t.Context())
	stop()
	if err := migrate.Rollback(cancelled, pool, steps, 0); err != nil {
		t.Fatalf("Rollback(0) with a cancelled context and a held turn: %v; want nil", err)
		return
	}
	if after := sqliteSchemaSnapshot(t, pool); !slices.Equal(before, after) {
		t.Fatalf("SQLite schema changed after Rollback(0): before=%v, after=%+v", before, after)
	}
}

package main_test

import (
	"encoding/json/v2"
	"os"
	"strings"
	"testing"

	sqlcgen "github.com/gosuda/spira/cmd/sqlc-gen-spira"
)

type continuedStringCase struct {
	Name  string `json:"name"`
	SQL   string `json:"sql"`
	Allow bool   `json:"allow"`
}

func TestPostgresContinuedEscapeStrings(t *testing.T) {
	data, err := os.ReadFile("testdata/continued-strings.json")
	if err != nil {
		t.Fatal(err)
		return
	}
	var cases []continuedStringCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
		return
	}
	if len(cases) != 14 {
		t.Fatalf("continued-string cases = %d; want 14", len(cases))
		return
	}
	for _, tc := range cases {
		t.Run(tc.Name, func(t *testing.T) {
			checkContinuedString(t, tc)
		})
	}
}

func checkContinuedString(t *testing.T, tc continuedStringCase) {
	t.Helper()
	req := loadRequest(t, "postgresql")
	req.PluginOptions = pluginOptions(t, map[string]any{
		"tables": map[string]any{
			"items": map[string]any{"type": "Item", "key": "id", "key_type": "ItemID", "version": "version"},
		},
	})
	req.Queries = []sqlcgen.Query{{
		Name: "ContinueItem", Cmd: ":exec", Filename: "items.sql", Text: tc.SQL,
	}}
	model, files, err := sqlcgen.Generate(req)
	if !tc.Allow {
		if err == nil {
			t.Fatal("Generate accepted a write whose version appears only in literal data or comments")
			return
		}
		if !strings.Contains(err.Error(), "writes versioned table items without version") {
			t.Fatalf("Generate refusal = %v; want the version refusal", err)
		}
		return
	}
	if err != nil {
		t.Fatalf("Generate rejected native-valid versioned SQL %q: %v", tc.SQL, err)
		return
	}
	if model.Engine != "postgresql" || len(files) == 0 {
		t.Fatalf("Generate result = %q, %d files; want PostgreSQL output", model.Engine, len(files))
		return
	}
	query := findQuery(t, model, "ContinueItem")
	if query.Text != tc.SQL {
		t.Fatalf("generated SQL = %q; want exact input %q", query.Text, tc.SQL)
	}
}
